// were last saved by, and for anything older than 2.4.0 it opens a notice
// about moving profile sync from Bambu Cloud to Orca Cloud, over the
// welcome-back window. Erasing it instead would turn auto-backup back on.
json carried_settings(json settings)
{
    if (!settings.is_object())
        return settings;
    settings.erase("jusprin_server");
    if (auto app = settings.find("app"); app != settings.end() && app->is_object())
        (*app)["version"] = SoftFever_VERSION;
    return settings;
}

